# Try more transformations
def sort_rows(grid):
    return [sorted(row) for row in grid]

def rotate_90_cw(grid):
    n = len(grid)
    return [[grid[n-1-j][i] for j in range(n)] for i in range(n)]

def reverse_rows(grid):
    return [row[::-1] for row in grid]

def flip_horizontal(grid):
    return [row[::-1] for row in grid]

def rotate_90_ccw(grid):
    n = len(grid)
    return [[grid[j][n-1-i] for j in range(n)] for i in range(n)]

def flip_vertical(grid):
    return grid[::-1]

def transpose(grid):
    return list(zip(*grid))

def rotate_180(grid):
    n = len(grid)
    return [[grid[n-1-i][n-1-j] for j in range(n)] for i in range(n)]

grid = [[7, 0, 1], [9, 8, 2], [4, 3, 6]]

print("Original:", grid)
print("Rotate 90 CW:", rotate_90_cw(grid))
print("Sort rows:", sort_rows(grid))
print("Reverse rows (flip H):", flip_horizontal(grid))
print("Rotate 90 CCW:", rotate_90_ccw(grid))
print("Flip vertical:", flip_vertical(grid))
print("Transpose:", list(zip(*grid)))
print("Rotate 180:", rotate_180(grid))
